import{_ as s,o as a,c as e,a2 as t}from"./chunks/framework.vLhlLNVn.js";const g=JSON.parse('{"title":"Installation & Toolchain","description":"","frontmatter":{},"headers":[],"relativePath":"guide/installation.md","filePath":"guide/installation.md","lastUpdated":null}'),n={name:"guide/installation.md"};function l(o,i,p,h,r,d){return a(),e("div",null,[...i[0]||(i[0]=[t(`<h1 id="installation-toolchain" tabindex="-1">Installation &amp; Toolchain <a class="header-anchor" href="#installation-toolchain" aria-label="Permalink to &quot;Installation &amp; Toolchain&quot;">​</a></h1><p>The Myelin compiler toolchain is distributed as a single unified executable: <code>myelinc</code>.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><a href="https://rustup.rs/" target="_blank" rel="noreferrer">Rust &amp; Cargo</a> (version 1.80 or later recommended)</li><li>Windows, macOS, or Linux</li></ul><hr><h2 id="building-from-source" tabindex="-1">Building from Source <a class="header-anchor" href="#building-from-source" aria-label="Permalink to &quot;Building from Source&quot;">​</a></h2><p>Clone the repository and compile <code>myelinc</code> in release mode:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/can/ailang.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ailang</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run all unit tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build the optimized compiler binary</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myelinc</span></span></code></pre></div><p>The compiled binary will be placed at:</p><ul><li><strong>Windows:</strong> <code>target/release/myelinc.exe</code></li><li><strong>Linux / macOS:</strong> <code>target/release/myelinc</code></li></ul><p>You can move <code>myelinc</code> to any directory in your system <code>$PATH</code> (e.g. <code>C:\\Windows\\System32</code> or <code>/usr/local/bin</code>).</p><hr><h2 id="cli-overview" tabindex="-1">CLI Overview <a class="header-anchor" href="#cli-overview" aria-label="Permalink to &quot;CLI Overview&quot;">​</a></h2><p><code>myelinc</code> provides commands tailored for both human developers and autonomous AI agents:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myelinc</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">COMMAN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">file.my</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--llm]</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:left;">Command</th><th style="text-align:left;">Description</th></tr></thead><tbody><tr><td style="text-align:left;"><code>myelinc run &lt;file.myl&gt;</code></td><td style="text-align:left;">Executes the Myelin source file using the built-in driverless runtime.</td></tr><tr><td style="text-align:left;"><code>myelinc check &lt;file.myl&gt;</code></td><td style="text-align:left;">Runs the lexer, parser, and semantic verifier without executing.</td></tr><tr><td style="text-align:left;"><code>myelinc parse &lt;file.myl&gt;</code></td><td style="text-align:left;">Prints the Abstract Syntax Tree (AST) representation.</td></tr><tr><td style="text-align:left;"><code>myelinc lex &lt;file.myl&gt;</code></td><td style="text-align:left;">Prints the raw token stream with line &amp; column spans.</td></tr><tr><td style="text-align:left;"><code>--llm</code> flag</td><td style="text-align:left;">Formats all diagnostics into single-line machine repair hints.</td></tr></tbody></table><hr><h2 id="running-your-first-program" tabindex="-1">Running Your First Program <a class="header-anchor" href="#running-your-first-program" aria-label="Permalink to &quot;Running Your First Program&quot;">​</a></h2><p>Create a file named <code>hello.myl</code>:</p><div class="language-myelin vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">myelin</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#mod</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> main</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#fn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> main [] </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">!io</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  io.println </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Hello from Myelin!&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  io.println </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;The LLM-Native Systems Programming Language&quot;</span></span></code></pre></div><p>Run it immediately:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myelinc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.myl</span></span></code></pre></div><p>Output:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Hello from Myelin!</span></span>
<span class="line"><span>The LLM-Native Systems Programming Language</span></span>
<span class="line"><span>Execution completed in 412 µs</span></span></code></pre></div><hr><h2 id="autonomous-agent-mode-llm" tabindex="-1">Autonomous Agent Mode (<code>--llm</code>) <a class="header-anchor" href="#autonomous-agent-mode-llm" aria-label="Permalink to &quot;Autonomous Agent Mode (\`--llm\`)&quot;">​</a></h2><p>When invoking <code>myelinc</code> from an AI agent or automated script, always add <code>--llm</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">myelinc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.myl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --llm</span></span></code></pre></div><p>If the file contains syntax or semantic issues, <code>myelinc</code> responds with a high-density, single-line format:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ERR E002 hello.myl:4:3 | odd_indent spaces=3 | fix: align statement to 2 or 4 spaces</span></span></code></pre></div><p>Agents can parse this output with a simple regex and make instant edits without wasting context tokens.</p>`,31)])])}const k=s(n,[["render",l]]);export{g as __pageData,k as default};
